import { hash, verify } from 'argon2';

// unique random salt is generated internally per hash
const stored = await hash(password); // work factor tuned so verify() stays under ~200ms

// constant-time comparison inside verify; never === on hashes or passwords yourself
const ok = await verify(stored, loginPassword);
if (!ok) throw new Error('invalid credentials'); // same message for unknown user

// mint a fresh session id at login, defeats fixation
const sid = crypto.randomBytes(32).toString('base64url');
await store.create(sid, user.id);
res.cookie('session', sid, {
    httpOnly: true,   // invisible to JavaScript
    secure: true,     // never over plain HTTP
    sameSite: 'lax',  // blocks cross-site sends
});

// the tagged template parameterizes values, same as the ORM itself
